-- 데모 공지 (업무 04, demo.notice): 테이블 이관 상태 예제 (수행 2 · 대기 2 · 이관 제외 2)
-- 새 볼륨은 01_init.sh 가 DEMO 계정으로 실행. 이미 있는 볼륨은: ./run-scripts/run-docker.sh notice
SET DEFINE OFF
WHENEVER SQLERROR CONTINUE

-- NTC_NOTICE : 공지사항 (TOBE tb_notice, 수행)
CREATE TABLE "NTC_NOTICE" (
      "NOTICE_ID" NUMBER(10) NOT NULL
    , "TITLE" VARCHAR2(200 CHAR) NOT NULL
    , "CONTENT" VARCHAR2(2000 CHAR)
    , "NOTICE_TYPE_CD" CHAR(1 CHAR)
    , "TOP_YN" CHAR(1 CHAR)
    , "VIEW_CNT" NUMBER(10)
    , "POST_START_DT" DATE
    , "REG_ID" VARCHAR2(40 CHAR)
    , "REG_DATE" DATE
    , "MOD_ID" VARCHAR2(40 CHAR)
    , "MOD_DATE" DATE
    , CONSTRAINT "PK_NTC_NOTICE" PRIMARY KEY ("NOTICE_ID")
);
COMMENT ON TABLE "NTC_NOTICE" IS '공지사항';

-- NTC_FAQ : 자주 묻는 질문 (TOBE tb_faq, 수행)
CREATE TABLE "NTC_FAQ" (
      "FAQ_ID" NUMBER(10) NOT NULL
    , "CATEGORY_CD" VARCHAR2(20 CHAR)
    , "QUESTION" VARCHAR2(500 CHAR) NOT NULL
    , "ANSWER" VARCHAR2(2000 CHAR)
    , "SORT_NO" NUMBER(5)
    , "USE_YN" CHAR(1 CHAR)
    , "REG_ID" VARCHAR2(40 CHAR)
    , "REG_DATE" DATE
    , "MOD_ID" VARCHAR2(40 CHAR)
    , "MOD_DATE" DATE
    , CONSTRAINT "PK_NTC_FAQ" PRIMARY KEY ("FAQ_ID")
);
COMMENT ON TABLE "NTC_FAQ" IS '자주 묻는 질문';

-- NTC_POPUP : 팝업 (TOBE tb_popup, 대기)
CREATE TABLE "NTC_POPUP" (
      "POPUP_ID" NUMBER(10) NOT NULL
    , "POPUP_NM" VARCHAR2(100 CHAR) NOT NULL
    , "START_DT" DATE
    , "END_DT" DATE
    , "WIDTH" NUMBER(5)
    , "HEIGHT" NUMBER(5)
    , "LINK_URL" VARCHAR2(500 CHAR)
    , "USE_YN" CHAR(1 CHAR)
    , "REG_ID" VARCHAR2(40 CHAR)
    , "REG_DATE" DATE
    , "MOD_ID" VARCHAR2(40 CHAR)
    , "MOD_DATE" DATE
    , CONSTRAINT "PK_NTC_POPUP" PRIMARY KEY ("POPUP_ID")
);
COMMENT ON TABLE "NTC_POPUP" IS '팝업';

-- NTC_BANNER : 배너 (TOBE tb_banner, 대기)
CREATE TABLE "NTC_BANNER" (
      "BANNER_ID" NUMBER(10) NOT NULL
    , "BANNER_NM" VARCHAR2(100 CHAR) NOT NULL
    , "IMG_PATH" VARCHAR2(300 CHAR)
    , "LINK_URL" VARCHAR2(500 CHAR)
    , "SORT_NO" NUMBER(5)
    , "USE_YN" CHAR(1 CHAR)
    , "REG_ID" VARCHAR2(40 CHAR)
    , "REG_DATE" DATE
    , "MOD_ID" VARCHAR2(40 CHAR)
    , "MOD_DATE" DATE
    , CONSTRAINT "PK_NTC_BANNER" PRIMARY KEY ("BANNER_ID")
);
COMMENT ON TABLE "NTC_BANNER" IS '배너';

-- NTC_READ_LOG : 공지 읽음 이력 (TOBE tb_notice_read_log, 이관 제외)
CREATE TABLE "NTC_READ_LOG" (
      "READ_ID" NUMBER(19) NOT NULL
    , "NOTICE_ID" NUMBER(10) NOT NULL
    , "MEMBER_ID" NUMBER(10)
    , "READ_DT" DATE
    , CONSTRAINT "PK_NTC_READ_LOG" PRIMARY KEY ("READ_ID")
);
COMMENT ON TABLE "NTC_READ_LOG" IS '공지 읽음 이력';

-- NTC_TEMPLATE : 공지 템플릿 (TOBE tb_notice_template, 이관 제외)
CREATE TABLE "NTC_TEMPLATE" (
      "TEMPLATE_ID" NUMBER(10) NOT NULL
    , "TEMPLATE_NM" VARCHAR2(100 CHAR) NOT NULL
    , "BODY_HTML" VARCHAR2(2000 CHAR)
    , "USE_YN" CHAR(1 CHAR)
    , "REG_ID" VARCHAR2(40 CHAR)
    , "REG_DATE" DATE
    , "MOD_ID" VARCHAR2(40 CHAR)
    , "MOD_DATE" DATE
    , CONSTRAINT "PK_NTC_TEMPLATE" PRIMARY KEY ("TEMPLATE_ID")
);
COMMENT ON TABLE "NTC_TEMPLATE" IS '공지 템플릿';

-- 앱 접속 계정(MIGRATOR)은 읽기만
GRANT SELECT ON "NTC_NOTICE" TO "MIGRATOR";
GRANT SELECT ON "NTC_FAQ" TO "MIGRATOR";
GRANT SELECT ON "NTC_POPUP" TO "MIGRATOR";
GRANT SELECT ON "NTC_BANNER" TO "MIGRATOR";
GRANT SELECT ON "NTC_READ_LOG" TO "MIGRATOR";
GRANT SELECT ON "NTC_TEMPLATE" TO "MIGRATOR";

